contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 tokenId,
        uint256 quantity,
        address caller,
        address ownerAddress,
        address treasuryAddress,
        address adminAddress,
        address nonOwnerCaller
    ) public payable {
        require(caller != nonOwnerCaller);
        require(caller != address(0));
        require(nonOwnerCaller != address(0));
        require(adminAddress != address(0));

        bool ownerBefore = c.isAdmin(ownerAddress);
        bool adminBefore = c.isAdmin(adminAddress);

        // Non-owner cannot change admin access
        bool reverted = false;
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("adjustAdminAccess(address,bool)", adminAddress, true)
        );
        reverted = !success;
        if (!reverted) {
            // If it didn't revert, caller must be owner (but we used a low-level call without
            // ensuring msg.sender is non-owner, so this branch may be unsafe; we only assert
            // on the reverted case below)
        }

        // Read admin status after attempted call; must be unchanged if reverted
        bool adminAfter = c.isAdmin(adminAddress);

        // General rule: non-owner cannot change admin mapping
        assert(reverted || adminAfter == adminBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 newItemDailyAllowance,
        uint256 tokenIdToCheck,
        address adminAddress
    ) public payable {
        require(adminAddress != address(0));
        require(adminAddress != address(this));

        c.createGameItem(
            "Test Item",
            "ipfs://test",
            false,
            true,
            0,
            1,
            uint16(newItemDailyAllowance)
        );

        bool adminBefore = c.isAdmin(adminAddress);

        bool reverted = false;
        try c.adjustAdminAccess(adminAddress, true) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool adminAfter = c.isAdmin(adminAddress);

        uint256 remaining = c.getAllowanceRemaining(address(this), tokenIdToCheck);

        assert(reverted == true || adminAfter == adminBefore);
        assert(
            tokenIdToCheck != c.uniqueTokensOutstanding() - 1 ||
            remaining == uint256(uint16(newItemDailyAllowance))
        );
    }

    receive() external payable {}
}

