contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address admin, address recipient, uint256 amount) public payable {
        require(admin != address(0));
        require(recipient != address(0));
        require(amount > 0);

        c.adjustAdminAccess(admin, true);
        c.setupAirdrop(_toArray(recipient), _toArray(amount));

        address treasury = c.treasuryAddress();
        uint256 beforeAllowance = c.allowance(treasury, recipient);

        bool reverted;
        try c.claim(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted || c.allowance(treasury, recipient) >= beforeAllowance - amount);
    }

    function _toArray(address x) private pure returns (address[] memory arr) {
        arr = new address[](1);
        arr[0] = x;
    }

    function _toArray(uint256 x) private pure returns (uint256[] memory arr) {
        arr = new uint256[](1);
        arr[0] = x;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 tokenId, uint256 quantity, uint256 nrnAmount) public payable {
        require(quantity > 0);

        // --- create a game item as admin so tokenId exists ---
        c.createGameItem(
            "Test Item",
            "ipfs://test",
            false,          // finiteSupply = false
            true,           // transferable = true
            0,              // itemsRemaining (unused for non-finite)
            1,              // itemPrice = 1 NRN per unit
            1000            // dailyAllowance
        );

        require(tokenId == 0);

        // --- deploy a Neuron contract to use as the payment token ---
        Neuron nrn = new Neuron(address(this), address(this), address(this));
        c.instantiateNeuronContract(address(nrn));

        // owner (this contract) is admin & minter; mint enough NRN to this contract
        nrn.mint(address(this), nrnAmount);

        // approve the game item contract to spend NRN on our behalf
        nrn.approve(address(c), nrnAmount);

        uint256 beforeBalance = c.balanceOf(address(this), tokenId);

        bool reverted;
        try c.mint(tokenId, quantity) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balanceOf(address(this), tokenId);

        // Successful mint must increase the caller's balance by exactly `quantity`.
        // (Reverts are allowed for arbitrary parameters; the rule is about the
        // success path.)
        assert(reverted || afterBalance == beforeBalance + quantity);
    }
}

